export const envelope = [56, 16, 18];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  // --- Palette Extraction & Helpers ---
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLogRaw = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStrippedRaw = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairsRaw = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlabRaw = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFenceRaw = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoorRaw = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:cobblestone";
  const stoneStairsRaw = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlabRaw = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWallRaw = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const groundPave = api.theme?.ground?.pavement || "minecraft:cobblestone";
  const groundRevet = api.theme?.ground?.revetment || "minecraft:mossy_cobblestone";

  const roofStairsRaw = api.theme?.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlabRaw = api.theme?.roof?.slab || "minecraft:dark_oak_slab";

  function clean(raw) {
    return raw ? raw.split("[")[0] : "";
  }

  function stair(raw, facing, half = "bottom", shape = "straight") {
    return `${clean(raw)}[facing=${facing},half=${half},shape=${shape},waterlogged=false]`;
  }

  function slab(raw, type = "bottom") {
    return `${clean(raw)}[type=${type},waterlogged=false]`;
  }

  function trapdoor(raw, facing = "north", half = "bottom", open = "false") {
    return `${clean(raw)}[facing=${facing},half=${half},open=${open},waterlogged=false]`;
  }

  function fence(raw, north = "false", south = "false", east = "false", west = "false") {
    return `${clean(raw)}[north=${north},south=${south},east=${east},west=${west},waterlogged=false]`;
  }

  function log(raw, axis = "y") {
    return `${clean(raw)}[axis=${axis}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  // --- Catenary Cable Function ---
  function cableY(x) {
    const mid = 27.5;
    const span = 17.5;
    const t = (x - mid) / span;
    const sag = 2.8 * (1.0 - t * t);
    return Math.round(12 - sag);
  }

  // =========================================================================
  // 1. LEFT SHORE — THE STONE VILLAGE QUAY & WINCH BASTION (X = 0 .. 13)
  // =========================================================================

  for (let x = 0; x <= 13; x++) {
    for (let z = 1; z <= 16; z++) {
      const h = Math.round(api.heightAt(x, z));
      const terrainY = clamp(seatY + h, 0, H - 1);
      const isSlipway = (x >= 10 && x <= 13 && z >= 6 && z <= 11);
      const deckY = isSlipway ? (x === 13 ? 4 : 5) : 5;

      // Deep foundation to terrain
      if (terrainY < deckY) {
        for (let y = terrainY; y < deckY; y++) {
          const block = (y === terrainY || api.random() > 0.4) ? groundRevet : stoneAccent;
          setBlock(x, y, z, block);
        }
      } else if (terrainY > deckY) {
        // High ground retaining wall
        for (let y = deckY; y <= terrainY; y++) {
          setBlock(x, y, z, (y === terrainY) ? groundPave : stonePrimary);
        }
      }

      // Deck surface course
      if (isSlipway) {
        if (x === 13) {
          setBlock(x, 4, z, stair(stoneStairsRaw, "east", "bottom"));
        } else if (x === 12) {
          setBlock(x, 5, z, stair(stoneStairsRaw, "east", "bottom"));
        } else {
          setBlock(x, 5, z, stonePrimary);
        }
      } else {
        const pave = (api.random() > 0.35) ? stonePrimary : ((api.random() > 0.5) ? groundPave : stoneAccent);
        setBlock(x, 5, z, pave);
      }
    }
  }

  // Stone Winch House / Bastion Walls (X: 1..6, Z: 5..12, Y: 5..9)
  for (let x = 1; x <= 6; x++) {
    for (let z = 5; z <= 12; z++) {
      const isOuter = (x === 1 || x === 6 || z === 5 || z === 12);
      if (isOuter) {
        for (let y = 6; y <= 9; y++) {
          // East archway opening (facing ferry)
          if (x === 6 && (z === 8 || z === 9) && y <= 8) {
            if (y === 8) {
              setBlock(x, y, z, stair(stoneStairsRaw, "east", "top"));
            }
            continue;
          }
          // West doorway
          if (x === 1 && (z === 8 || z === 9) && y <= 7) {
            continue;
          }
          // Window embrasures
          if ((z === 5 || z === 12) && (x === 3 || x === 4) && y === 7) {
            setBlock(x, y, z, "minecraft:iron_bars");
            continue;
          }
          const wallBlock = (api.random() > 0.3) ? stonePrimary : stoneAccent;
          setBlock(x, y, z, wallBlock);
        }
      }
    }
  }

  // Bastion Slate Roof (Y: 9..11)
  for (let z = 4; z <= 13; z++) {
    setBlock(0, 9, z, stair(roofStairsRaw, "east", "bottom"));
    setBlock(1, 10, z, stair(roofStairsRaw, "east", "bottom"));
    setBlock(2, 10, z, slab(roofSlabRaw, "top"));
    setBlock(3, 11, z, slab(roofSlabRaw, "bottom"));
    setBlock(4, 11, z, slab(roofSlabRaw, "bottom"));
    setBlock(5, 10, z, slab(roofSlabRaw, "top"));
    setBlock(6, 10, z, stair(roofStairsRaw, "west", "bottom"));
    setBlock(7, 9, z, stair(roofStairsRaw, "west", "bottom"));
  }

  // Winch Mechanism inside stone bastion (X: 4..5, Z: 8..9, Y: 6..7)
  setBlock(4, 6, 8, log(woodStrippedRaw, "z"));
  setBlock(4, 6, 9, log(woodStrippedRaw, "z"));
  setBlock(5, 6, 8, "minecraft:grindstone[face=wall,facing=east]");
  setBlock(5, 6, 9, "minecraft:grindstone[face=wall,facing=east]");
  setBlock(4, 7, 8, "minecraft:chain[axis=z]");
  setBlock(4, 7, 9, "minecraft:chain[axis=z]");

  // Stone Cable Towers / Pylons (X: 9..10, Z: 4..5 and Z: 12..13, Y: 5..12)
  for (let zRange of [[4, 5], [12, 13]]) {
    for (let x = 9; x <= 10; x++) {
      for (let z = zRange[0]; z <= zRange[1]; z++) {
        for (let y = 6; y <= 11; y++) {
          setBlock(x, y, z, stonePrimary);
        }
      }
    }
    const centerZ = zRange[0] === 4 ? 5 : 12;
    setBlock(10, 12, centerZ, "minecraft:grindstone[face=floor,facing=east]");
    setBlock(9, 12, centerZ, stoneWallRaw);
    // Tower crowning details
    setBlock(9, 13, centerZ, "minecraft:lantern[hanging=false]");
  }

  // Backstay tension chains on stone side
  for (let x = 3; x <= 9; x++) {
    const yStay = Math.round(7 + (x - 3) * (5 / 6));
    setBlock(x, yStay, 5, "minecraft:chain[axis=x]");
    setBlock(x, yStay, 12, "minecraft:chain[axis=x]");
  }

  // Stone Quay Details & Parapets
  for (let x = 7; x <= 12; x++) {
    setBlock(x, 6, 3, stoneWallRaw);
    setBlock(x, 6, 14, stoneWallRaw);
  }
  // Bollards
  setBlock(12, 6, 4, stoneWallRaw);
  setBlock(12, 7, 4, slab(stoneSlabRaw, "bottom"));
  setBlock(12, 6, 13, stoneWallRaw);
  setBlock(12, 7, 13, slab(stoneSlabRaw, "bottom"));
  setBlock(8, 6, 3, stoneWallRaw);
  setBlock(8, 7, 3, "minecraft:lantern[hanging=false]");
  setBlock(8, 6, 14, stoneWallRaw);
  setBlock(8, 7, 14, "minecraft:lantern[hanging=false]");

  // =========================================================================
  // 2. RIGHT SHORE — TIMBER VILLAGE DOCK & GANTRY SHACK (X = 42 .. 55)
  // =========================================================================

  for (let x = 42; x <= 55; x++) {
    for (let z = 1; z <= 16; z++) {
      const h = Math.round(api.heightAt(x, z));
      const terrainY = clamp(seatY + h, 0, H - 1);
      const isSlipway = (x >= 42 && x <= 45 && z >= 6 && z <= 11);
      const isUpperTerrace = (x >= 48);
      const deckY = isUpperTerrace ? 6 : (isSlipway ? (x === 42 ? 4 : 5) : 5);

      // Piles on grid columns or cribbing along shore bank
      const isPileCol = (x % 3 === 0 && (z === 2 || z === 5 || z === 8 || z === 11 || z === 14 || z === 15));
      if (isPileCol || isUpperTerrace) {
        if (terrainY < deckY) {
          for (let y = terrainY; y < deckY; y++) {
            setBlock(x, y, z, log(woodLogRaw, "y"));
          }
        } else if (terrainY > deckY) {
          for (let y = deckY; y <= terrainY; y++) {
            setBlock(x, y, z, woodPlanks);
          }
        }
      }

      // Deck surface course
      if (isSlipway) {
        if (x === 42) {
          setBlock(x, 4, z, stair(woodStairsRaw, "west", "bottom"));
        } else if (x === 43) {
          setBlock(x, 5, z, stair(woodStairsRaw, "west", "bottom"));
        } else {
          setBlock(x, 5, z, woodPlanks);
        }
      } else if (isUpperTerrace) {
        setBlock(x, 6, z, woodPlanks);
      } else {
        setBlock(x, 5, z, (z % 2 === 0) ? woodPlanks : slab(woodSlabRaw, "top"));
      }
    }
  }

  // Steps between lower dock (Y=5) and upper terrace (Y=6)
  for (let z = 3; z <= 14; z++) {
    if (z < 6 || z > 11) {
      setBlock(47, 6, z, stair(woodStairsRaw, "west", "bottom"));
    }
  }

  // Timber Gantry / Watchman's Shack (X: 48..54, Z: 5..12, Y: 6..10)
  for (let x = 48; x <= 54; x++) {
    for (let z = 5; z <= 12; z++) {
      const isCorner = (x === 48 || x === 54) && (z === 5 || z === 12);
      const isWall = (x === 48 || x === 54 || z === 5 || z === 12);

      if (isCorner) {
        for (let y = 6; y <= 10; y++) {
          setBlock(x, y, z, log(woodLogRaw, "y"));
        }
      } else if (isWall) {
        for (let y = 7; y <= 10; y++) {
          // West door to dock
          if (x === 48 && (z === 8 || z === 9) && y <= 8) continue;
          // East door to village
          if (x === 54 && (z === 8 || z === 9) && y <= 8) continue;
          // Window fences
          if ((z === 5 || z === 12) && (x === 50 || x === 52) && y === 8) {
            setBlock(x, y, z, fence(woodFenceRaw, "true", "true", "false", "false"));
            continue;
          }
          setBlock(x, y, z, (y === 10) ? log(woodStrippedRaw, "x") : woodPlanks);
        }
      }
    }
  }

  // Steep Timber Shingle Roof (Y: 10..14)
  for (let z = 4; z <= 13; z++) {
    setBlock(47, 10, z, stair(woodStairsRaw, "east", "bottom"));
    setBlock(48, 11, z, stair(woodStairsRaw, "east", "bottom"));
    setBlock(49, 12, z, stair(woodStairsRaw, "east", "bottom"));
    setBlock(50, 13, z, stair(woodStairsRaw, "east", "bottom"));
    setBlock(51, 14, z, slab(woodSlabRaw, "bottom"));
    setBlock(52, 13, z, stair(woodStairsRaw, "west", "bottom"));
    setBlock(53, 12, z, stair(woodStairsRaw, "west", "bottom"));
    setBlock(54, 11, z, stair(woodStairsRaw, "west", "bottom"));
    setBlock(55, 10, z, stair(woodStairsRaw, "west", "bottom"));
  }

  // Timber A-Frame Cable Tower (X: 45..46, Z: 4..5 and Z: 12..13, Y: 5..12)
  for (let zRange of [[4, 5], [12, 13]]) {
    const centerZ = zRange[0] === 4 ? 5 : 12;
    for (let y = 6; y <= 11; y++) {
      setBlock(45, y, centerZ, log(woodLogRaw, "y"));
      setBlock(46, y, centerZ, log(woodStrippedRaw, "y"));
    }
    setBlock(45, 12, centerZ, "minecraft:grindstone[face=floor,facing=west]");
    setBlock(46, 12, centerZ, fence(woodFenceRaw, "true", "true", "false", "false"));
    setBlock(46, 13, centerZ, "minecraft:lantern[hanging=false]");
  }
  // Gantry cross-beam at Y=12
  for (let z = 5; z <= 12; z++) {
    setBlock(45, 12, z, log(woodStrippedRaw, "z"));
  }

  // Spoked Capstan Wheel on Timber Dock (X: 46..47, Z: 8..9, Y: 6..8)
  setBlock(46, 6, 8, log(woodStrippedRaw, "y"));
  setBlock(46, 7, 8, log(woodStrippedRaw, "y"));
  setBlock(46, 7, 7, fence(woodFenceRaw, "true", "true", "false", "false")); // spoke North
  setBlock(46, 7, 9, fence(woodFenceRaw, "true", "true", "false", "false")); // spoke South
  setBlock(45, 7, 8, fence(woodFenceRaw, "false", "false", "true", "true")); // spoke West
  setBlock(47, 7, 8, fence(woodFenceRaw, "false", "false", "true", "true")); // spoke East
  setBlock(46, 8, 8, "minecraft:grindstone[face=floor,facing=north]");

  // Backstay struts from Timber Gantry
  for (let x = 46; x <= 52; x++) {
    const yStay = Math.round(12 - (x - 45) * (5 / 7));
    setBlock(x, yStay, 5, "minecraft:chain[axis=x]");
    setBlock(x, yStay, 12, "minecraft:chain[axis=x]");
  }

  // Fish Drying Racks on Timber Dock Flanks
  for (let z of [2, 3, 14, 15]) {
    for (let x = 44; x <= 47; x++) {
      if (x === 44 || x === 47) {
        setBlock(x, 6, z, fence(woodFenceRaw, "false", "false", "true", "true"));
      }
      setBlock(x, 7, z, fence(woodFenceRaw, "false", "false", "true", "true"));
      setBlock(x, 6, z, trapdoor(woodTrapdoorRaw, "north", "top", "true"));
    }
  }

  // Timber Bollards & Crates
  setBlock(43, 6, 4, log(woodLogRaw, "y"));
  setBlock(43, 7, 4, trapdoor(woodTrapdoorRaw, "north", "top", "false"));
  setBlock(43, 6, 13, log(woodLogRaw, "y"));
  setBlock(43, 7, 13, trapdoor(woodTrapdoorRaw, "north", "top", "false"));
  setBlock(48, 7, 4, "minecraft:barrel[facing=up]");
  setBlock(48, 7, 13, "minecraft:barrel[facing=up]");

  // =========================================================================
  // 3. OVERHEAD GUIDE CABLES & HAULAGE LINES (X = 10 .. 45)
  // =========================================================================

  for (let x = 10; x <= 45; x++) {
    const yNow = cableY(x);

    // North Cable (Z=5) & South Cable (Z=12)
    for (let z of [5, 12]) {
      setBlock(x, yNow, z, "minecraft:chain[axis=x]");
      if (x > 10) {
        const yPrev = cableY(x - 1);
        if (yNow !== yPrev) {
          const minY = Math.min(yNow, yPrev);
          const maxY = Math.max(yNow, yPrev);
          for (let y = minY; y <= maxY; y++) {
            setBlock(x, y, z, "minecraft:chain[axis=y]");
          }
        }
      }
    }

    // Central Haulage Ropes (Z=8 & Z=9)
    for (let z of [8, 9]) {
      setBlock(x, yNow, z, "minecraft:chain[axis=x]");
      if (x > 10) {
        const yPrev = cableY(x - 1);
        if (yNow !== yPrev) {
          const minY = Math.min(yNow, yPrev);
          const maxY = Math.max(yNow, yPrev);
          for (let y = minY; y <= maxY; y++) {
            setBlock(x, y, z, "minecraft:chain[axis=y]");
          }
        }
      }
    }

    // Cable Spacers / Cross-stays every 6 blocks
    if (x === 16 || x === 22 || x === 34 || x === 40) {
      for (let z = 6; z <= 11; z++) {
        setBlock(x, yNow, z, "minecraft:iron_bars");
      }
    }
  }

  // =========================================================================
  // 4. THE FERRY BARGE (X = 23 .. 33, Z = 5 .. 12)
  // =========================================================================

  // Barge Hull Bottom (Y = 5)
  for (let x = 23; x <= 33; x++) {
    for (let z = 5; z <= 12; z++) {
      const isBowStern = (x === 23 || x === 33);
      const isEdgeZ = (z === 5 || z === 12);

      if (isBowStern && isEdgeZ) {
        setBlock(x, 5, z, slab(woodSlabRaw, "top"));
      } else if (isBowStern) {
        const facing = (x === 23) ? "west" : "east";
        setBlock(x, 5, z, stair(woodStairsRaw, facing, "top"));
      } else if (isEdgeZ) {
        const facing = (z === 5) ? "north" : "south";
        setBlock(x, 5, z, stair(woodStairsRaw, facing, "top"));
      } else {
        setBlock(x, 5, z, woodPlanks);
      }
    }
  }

  // Barge Deck Floor (Y = 6)
  for (let x = 24; x <= 32; x++) {
    for (let z = 6; z <= 11; z++) {
      const isCenterPlank = (z === 8 || z === 9);
      setBlock(x, 6, z, isCenterPlank ? log(woodStrippedRaw, "x") : woodPlanks);
    }
  }

  // Barge Gunwales / Railings (Y = 7)
  for (let x = 24; x <= 32; x++) {
    setBlock(x, 7, 5, fence(woodFenceRaw, "false", "false", "true", "true"));
    setBlock(x, 7, 12, fence(woodFenceRaw, "false", "false", "true", "true"));
  }

  // Boarding Ramps / Aprons (X = 23 and X = 33)
  for (let z = 7; z <= 10; z++) {
    setBlock(23, 6, z, stair(woodStairsRaw, "west", "bottom"));
    setBlock(22, 5, z, slab(woodSlabRaw, "top"));
    setBlock(33, 6, z, stair(woodStairsRaw, "east", "bottom"));
    setBlock(34, 5, z, slab(woodSlabRaw, "top"));
  }
  // Ramp suspension chains
  setBlock(22, 6, 6, "minecraft:chain[axis=y]");
  setBlock(22, 6, 11, "minecraft:chain[axis=y]");
  setBlock(34, 6, 6, "minecraft:chain[axis=y]");
  setBlock(34, 6, 11, "minecraft:chain[axis=y]");

  // Barge Gantry Bents & Pulley Trolleys (X = 26 and X = 30)
  for (let xBent of [26, 30]) {
    const yTop = cableY(xBent);

    // Gantry uprights
    for (let y = 6; y <= yTop; y++) {
      setBlock(xBent, y, 5, log(woodLogRaw, "y"));
      setBlock(xBent, y, 6, fence(woodFenceRaw, "false", "false", "true", "true"));
      setBlock(xBent, y, 11, fence(woodFenceRaw, "false", "false", "true", "true"));
      setBlock(xBent, y, 12, log(woodLogRaw, "y"));
    }

    // Gantry Crossbeam
    for (let z = 5; z <= 12; z++) {
      setBlock(xBent, yTop, z, log(woodStrippedRaw, "z"));
    }

    // Pulley trolley blocks hooking onto cables
    setBlock(xBent, yTop, 5, "minecraft:grindstone[face=ceiling,facing=north]");
    setBlock(xBent, yTop, 8, "minecraft:grindstone[face=ceiling,facing=north]");
    setBlock(xBent, yTop, 9, "minecraft:grindstone[face=ceiling,facing=north]");
    setBlock(xBent, yTop, 12, "minecraft:grindstone[face=ceiling,facing=north]");

    // Hanging brass lanterns on barge
    setBlock(xBent, yTop - 1, 7, "minecraft:lantern[hanging=true]");
    setBlock(xBent, yTop - 1, 10, "minecraft:lantern[hanging=true]");
  }

  // Onboard Haulage Crank & Deck Cargo
  setBlock(28, 7, 8, log(woodStrippedRaw, "y"));
  setBlock(28, 8, 8, "minecraft:grindstone[face=floor,facing=east]");
  setBlock(28, 7, 9, "minecraft:iron_bars");
  setBlock(28, 8, 9, "minecraft:chain[axis=y]");

  // Fish Barrels & Crates on Deck
  setBlock(24, 7, 6, "minecraft:barrel[facing=up]");
  setBlock(24, 7, 7, "minecraft:barrel[facing=up]");
  setBlock(32, 7, 10, "minecraft:barrel[facing=up]");
  setBlock(32, 7, 11, "minecraft:barrel[facing=up]");
  setBlock(25, 7, 11, log(woodStrippedRaw, "y"));
  setBlock(25, 8, 11, trapdoor(woodTrapdoorRaw, "north", "bottom", "false"));

  // =========================================================================
  // 5. WATERWAY FENDER DOLPHINS & FAIRWAY BOOMS
  // =========================================================================

  // Stone-side dolphins at X=15, Z=4 and Z=13
  for (let z of [4, 13]) {
    const h = Math.round(api.heightAt(15, z));
    const seabedY = clamp(seatY + h, 0, H - 1);
    for (let y = seabedY; y <= 7; y++) {
      setBlock(15, y, z, log(woodLogRaw, "y"));
    }
    setBlock(15, 8, z, "minecraft:lantern[hanging=false]");
    // Horizontal fender booms connecting dolphin to quay
    setBlock(14, 5, z, log(woodStrippedRaw, "x"));
  }

  // Timber-side dolphins at X=40, Z=4 and Z=13
  for (let z of [4, 13]) {
    const h = Math.round(api.heightAt(40, z));
    const seabedY = clamp(seatY + h, 0, H - 1);
    for (let y = seabedY; y <= 7; y++) {
      setBlock(40, y, z, log(woodLogRaw, "y"));
    }
    setBlock(40, 8, z, "minecraft:lantern[hanging=false]");
    // Horizontal fender booms connecting dolphin to dock
    setBlock(41, 5, z, log(woodStrippedRaw, "x"));
  }

  // =========================================================================
  // INTERIORS & RETURN DEFINITION
  // =========================================================================

  const interiors = [
    {
      min: [2, 6, 6],
      max: [5, 8, 11],
      kind: "vault"
    },
    {
      min: [49, 7, 6],
      max: [53, 9, 11],
      kind: "quarters"
    }
  ];

  return {
    name: "Rope Ferry",
    seatY: 4,
    anchors: {
      front: [28, 6, 0],
      stone_dock: [6, 6, 8],
      timber_dock: [48, 6, 8],
      ferry_barge: [28, 6, 8]
    },
    interiors
  };
}
